WITH supplier_summary AS (SELECT supplier_id, SUM(CASE WHEN brand = 'Globex' THEN 1 ELSE 0 END) AS globex_count FROM products GROUP BY supplier_id) SELECT s.rating, ss.globex_count FROM suppliers s INNER JOIN supplier_summary ss ON s.id = ss.supplier_id WHERE ss.globex_count > 65 ORDER BY rating DESC;
